import React, { useState, useEffect } from 'react';
import SalesChart from '../Pages/Analytics/SalesChart';
import TrafficChart from '../Pages/Analytics/TrafficChart';
import StatisticsCards from '../Pages/Analytics/StatisticsCards';
import TopProducts from '../Pages/Analytics/TopProducts';
import RevenueChart from '../Pages/Analytics/RevenueChart';
import { 
  TrendingUp, Filter, Download, Calendar,
  BarChart3, PieChart, LineChart, Activity
} from 'lucide-react';

const AnalyticsPage = () => {
  const [timeRange, setTimeRange] = useState('month');
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');

  useEffect(() => {
    // Simuler le chargement
    const timer = setTimeout(() => setIsLoading(false), 1000);
    return () => clearTimeout(timer);
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <div className="h-16 w-16 rounded-full border-4 border-primary-500 border-t-transparent animate-spin mx-auto mb-4"></div>
          <p className="text-neutral-600 dark:text-neutral-400">Chargement des données...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      {/* Header avec actions */}
      <div className="mb-8">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-6">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-neutral-900 dark:text-white bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
              Tableau de bord analytique
            </h1>
            <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400 mt-1">
              Visualisez vos performances en temps réel
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {/* Période */}
            <div className="flex items-center space-x-2 bg-white dark:bg-neutral-800 rounded-2xl p-1 border border-neutral-200 dark:border-neutral-700">
              {['jour', 'semaine', 'mois', 'année'].map((range) => (
                <button
                  key={range}
                  onClick={() => setTimeRange(range)}
                  className={`px-4 py-2 rounded-xl text-sm font-medium transition-all duration-300 ${
                    timeRange === range
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                      : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700'
                  }`}
                >
                  {range.charAt(0).toUpperCase() + range.slice(1)}
                </button>
              ))}
            </div>

            {/* Actions */}
            <button className="flex items-center space-x-2 px-4 py-2.5 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl text-neutral-700 dark:text-neutral-300 hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-all duration-300 group">
              <Filter className="h-4 w-4" />
              <span className="text-sm font-medium">Filtres</span>
            </button>

            <button className="flex items-center space-x-2 px-4 py-2.5 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-2xl hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300 group">
              <Download className="h-4 w-4" />
              <span className="text-sm font-medium">Exporter</span>
            </button>
          </div>
        </div>

        {/* Onglets */}
        <div className="flex space-x-1 p-1 bg-white dark:bg-neutral-800 rounded-2xl border border-neutral-200 dark:border-neutral-700 max-w-max">
          {[
            { id: 'overview', label: 'Vue générale', icon: <Activity className="h-4 w-4" /> },
            { id: 'sales', label: 'Ventes', icon: <BarChart3 className="h-4 w-4" /> },
            { id: 'revenue', label: 'Revenus', icon: <LineChart className="h-4 w-4" /> },
            { id: 'traffic', label: 'Trafic', icon: <PieChart className="h-4 w-4" /> }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 px-6 py-3 rounded-xl text-sm font-medium transition-all duration-300 ${
                activeTab === tab.id
                  ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                  : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700'
              }`}
            >
              {tab.icon}
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Statistiques en haut */}
      <StatisticsCards timeRange={timeRange} />

      {/* Grille principale */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        <RevenueChart timeRange={timeRange} />
        <SalesChart timeRange={timeRange} />
        <TrafficChart timeRange={timeRange} />
        <TopProducts timeRange={timeRange} />
      </div>

      {/* Insights */}
      <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6 mb-8">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Insights et recommandations</h3>
          <TrendingUp className="h-5 w-5 text-primary-500" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {[
            { title: 'Conversion élevée', desc: 'Taux de conversion +15% cette semaine', trend: 'up' },
            { title: 'Trafic mobile', desc: '65% des visites proviennent du mobile', trend: 'up' },
            { title: 'Panier moyen', desc: 'Augmentation de 25€ cette semaine', trend: 'up' },
          ].map((insight, index) => (
            <div 
              key={index}
              className="p-4 rounded-2xl bg-gradient-to-br from-primary-50 to-primary-100/30 dark:from-primary-900/20 dark:to-primary-800/10 border border-primary-100 dark:border-primary-800/30 hover:scale-[1.02] transition-all duration-300"
            >
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-semibold text-neutral-900 dark:text-white">{insight.title}</h4>
                <div className={`h-8 w-8 rounded-full flex items-center justify-center ${
                  insight.trend === 'up' 
                    ? 'bg-green-500/10 text-green-600 dark:text-green-400' 
                    : 'bg-red-500/10 text-red-600 dark:text-red-400'
                }`}>
                  <TrendingUp className="h-4 w-4" />
                </div>
              </div>
              <p className="text-sm text-neutral-600 dark:text-neutral-400">{insight.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </>
  );
};

export default AnalyticsPage;
